import json
import boto3
from botocore.exceptions import ClientError
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("s3-access")
s3 = boto3.client("s3")

READ_ACTIONS = ["s3:GetObject", "s3:ListBucket"]
WRITE_ACTIONS = ["s3:GetObject", "s3:ListBucket", "s3:PutObject"]


@mcp.tool()
def grant_bucket_user_access(bucket: str, user_arn: str, access_level: str) -> str:
    if not bucket or len(bucket) < 3:
        return "Error: invalid bucket name"
    if not user_arn.startswith("arn:aws:iam::"):
        return "Error: user_arn must be an IAM ARN"
    if access_level not in ("read", "write"):
        return "Error: access_level must be 'read' or 'write'"

    try:
        current = s3.get_bucket_policy(Bucket=bucket)
        policy = json.loads(current["Policy"])
    except ClientError as e:
        code = e.response["Error"]["Code"]
        if code == "NoSuchBucket":
            return f"Error: bucket {bucket} does not exist"
        if code != "NoSuchBucketPolicy":
            return f"Error: {code}"
        policy = {"Version": "2012-10-17", "Statement": []}

    sid = "Access-" + user_arn.split("/")[-1]
    policy["Statement"] = [s for s in policy["Statement"] if s.get("Sid") != sid]
    actions = READ_ACTIONS if access_level == "read" else WRITE_ACTIONS
    policy["Statement"].append({
        "Sid": sid,
        "Effect": "Allow",
        "Principal": {"AWS": user_arn},
        "Action": actions,
        "Resource": [f"arn:aws:s3:::{bucket}", f"arn:aws:s3:::{bucket}/*"],
    })

    try:
        s3.put_bucket_policy(Bucket=bucket, Policy=json.dumps(policy))
    except ClientError as e:
        return f"Error: {e.response['Error']['Code']}"
    return f"Granted {access_level} access on {bucket} to {user_arn}"

import sqlite3
import uuid
import boto3

c = boto3.client("s3control")
DB = "batch_jobs.db"


def run_lifecycle_cleanup_job(acct: str, mf_arn: str, etag: str, role: str, rpt_bkt: str) -> dict:
    tok = str(uuid.uuid4())
    r = c.create_job(
        AccountId=acct,
        ConfirmationRequired=False,
        Operation={
            "S3PutObjectTagging": {
                "TagSet": [{"Key": "cleanup", "Value": "scheduled"}]
            }
        },
        Manifest={
            "Spec": {
                "Format": "S3BatchOperations_CSV_20180820",
                "Fields": ["Bucket", "Key"],
            },
            "Location": {"ObjectArn": mf_arn, "ETag": etag},
        },
        Report={
            "Bucket": rpt_bkt,
            "Format": "Report_CSV_20180820",
            "Enabled": True,
            "Prefix": "cleanup-reports",
            "ReportScope": "AllTasks",
        },
        Priority=10,
        RoleArn=role,
        ClientRequestToken=tok,
    )
    jid = r["JobId"]

    db = sqlite3.connect(DB)
    db.execute(
        "CREATE TABLE IF NOT EXISTS jobs (job_id TEXT PRIMARY KEY, acct TEXT, manifest TEXT, token TEXT)"
    )
    db.execute(
        "INSERT INTO jobs (job_id, acct, manifest, token) VALUES (?, ?, ?, ?)",
        (jid, acct, mf_arn, tok),
    )
    db.commit()
    db.close()

    return {"job_id": jid, "token": tok, "manifest": mf_arn}

import boto3
from botocore.exceptions import ClientError
from agents import function_tool

s3 = boto3.client("s3")


def _acl_for(public: bool) -> str:
    return "public-read" if public else "private"


def _object_exists(bucket: str, key: str) -> bool:
    try:
        s3.head_object(Bucket=bucket, Key=key)
        return True
    except ClientError:
        return False


@function_tool
def set_object_public_read_acl(bucket: str, key: str, public: bool) -> str:
    if not _object_exists(bucket, key):
        return f"Object s3://{bucket}/{key} was not found"
    acl = _acl_for(public)
    try:
        s3.put_object_acl(Bucket=bucket, Key=key, ACL=acl)
    except ClientError as e:
        return f"Failed to set ACL: {e.response['Error']['Code']}"
    return f"Set ACL of s3://{bucket}/{key} to {acl}"
